// IdentityServer is the server API for Identity service.
// All implementations must embed UnimplementedIdentityServer
// for forward compatibility.
//
// Identity 认证服务契约（S3-02，v4/03 阶段 3 任务正本）。
//
// 职责边界（02 §9.5）：identity 是会话与 auth_cache 的唯一写入方；
// MySQL 只存"账号是什么"，会话/锁定计数/权限快照在 Redis DB4（sessionx）。
// ID 传输用 int64（内部 RPC），对外（BFF → 前端）一律转 string 渲染（E8）。
type IdentityServer interface {
	Ping(context.Context, *PingReq) (*PingResp, error)
	// ---- 认证主链 ----
	// 密码登录：锁定校验 → argon2id → 互斥踢旧 → 写会话 → auth.login 审计（outbox）
	LoginByPassword(context.Context, *LoginByPasswordReq) (*LoginResp, error)
	// 微信登录：code2session；未绑手机返回 need_bind_phone（不签发 token）
	LoginByWechat(context.Context, *LoginByWechatReq) (*LoginByWechatResp, error)
	// refresh 轮换：重用检测（命中墓碑 → 全端注销 + 告警日志）
	Refresh(context.Context, *RefreshReq) (*RefreshResp, error)
	Logout(context.Context, *LogoutReq) (*LogoutResp, error)
	// step-up：校验密码 → RaiseLevel(sid,2)（5min）→ 重签 level=2 access
	StepUp(context.Context, *StepUpReq) (*StepUpResp, error)
	// 模拟他人（L2）：操作人须 step-up；审计 auth.impersonate
	Impersonate(context.Context, *ImpersonateReq) (*ImpersonateResp, error)
	// 统一账号-参与方绑定（S4 party 落地后消费）
	BindParty(context.Context, *BindPartyReq) (*BindPartyResp, error)
	// ---- 会话管理 ----
	ListSessions(context.Context, *ListSessionsReq) (*ListSessionsResp, error)
	KickSessions(context.Context, *KickSessionsReq) (*KickSessionsResp, error)
	ValidateSession(context.Context, *ValidateSessionReq) (*ValidateSessionResp, error)
	// ---- auth_cache（写入方与刷新源；BFF 每请求直接 GET Redis，本方法供刷新与排障）----
	GetAuthCache(context.Context, *GetAuthCacheReq) (*GetAuthCacheResp, error)
	// ---- 用户管理 ----
	CreateUser(context.Context, *CreateUserReq) (*CreateUserResp, error)
	UpdateUser(context.Context, *UpdateUserReq) (*UpdateUserResp, error)
	UpdateUserStatus(context.Context, *UpdateUserStatusReq) (*UpdateUserStatusResp, error)
	ResetPassword(context.Context, *ResetPasswordReq) (*ResetPasswordResp, error)
	DeleteUser(context.Context, *DeleteUserReq) (*DeleteUserResp, error)
	GetUser(context.Context, *GetUserReq) (*GetUserResp, error)
	ListUsers(context.Context, *ListUsersReq) (*ListUsersResp, error)
	// ---- 角色管理 ----
	CreateRole(context.Context, *CreateRoleReq) (*CreateRoleResp, error)
	UpdateRole(context.Context, *UpdateRoleReq) (*UpdateRoleResp, error)
	DeleteRole(context.Context, *DeleteRoleReq) (*DeleteRoleResp, error)
	GetRole(context.Context, *GetRoleReq) (*GetRoleResp, error)
	ListRoles(context.Context, *ListRolesReq) (*ListRolesResp, error)
	// ---- 组织管理 ----
	CreateOrg(context.Context, *CreateOrgReq) (*CreateOrgResp, error)
	UpdateOrg(context.Context, *UpdateOrgReq) (*UpdateOrgResp, error)
	DeleteOrg(context.Context, *DeleteOrgReq) (*DeleteOrgResp, error)
	ListOrgs(context.Context, *ListOrgsReq) (*ListOrgsResp, error)
	// ---- 菜单管理 ----
	CreateMenu(context.Context, *CreateMenuReq) (*CreateMenuResp, error)
	UpdateMenu(context.Context, *UpdateMenuReq) (*UpdateMenuResp, error)
	DeleteMenu(context.Context, *DeleteMenuReq) (*DeleteMenuResp, error)
	ListMenus(context.Context, *ListMenusReq) (*ListMenusResp, error)
	// 用户可见菜单（/auth/menus 数据源：用户全部角色 → 菜单并集）
	GetUserMenus(context.Context, *GetUserMenusReq) (*GetUserMenusResp, error)
	// ---- 租户管理 ----
	CreateTenant(context.Context, *CreateTenantReq) (*CreateTenantResp, error)
	UpdateTenant(context.Context, *UpdateTenantReq) (*UpdateTenantResp, error)
	UpdateTenantQuota(context.Context, *UpdateTenantQuotaReq) (*UpdateTenantQuotaResp, error)
	DeleteTenant(context.Context, *DeleteTenantReq) (*DeleteTenantResp, error)
	ListTenants(context.Context, *ListTenantsReq) (*ListTenantsResp, error)
	mustEmbedUnimplementedIdentityServer()
}

